@Entity()
export class Actor {
  @PrimaryGeneratedColumn() id!: number;
  @ManyToMany(() => Film, (film) => film.actors)      // inverse on Film.actors
  @JoinTable({ name: 'actor_film',
    joinColumn: { name: 'actor_id', referencedColumnName: 'id' },
    inverseJoinColumn: { name: 'film_id', referencedColumnName: 'id' } })
  films!: Film[];
}
// link row without loading the collection:
await dataSource.getRepository(Actor)
  .createQueryBuilder('a').relation(Actor, 'films').of(actorId).add(filmId);

