// Prisma manages the implicit relation table itself (_ActorToFilm, columns A and B);
// the explicit form declares the relation table as a model with a composite id:
model ActorFilm {
  actor     Actor    @relation(fields: [actorId], references: [id])
  actorId   Int
  film      Film     @relation(fields: [filmId], references: [id])
  filmId    Int
  castSince DateTime @default(now())   // association payload
  @@id([actorId, filmId])
}
